<template>
    <main class="auth-login-page">
        <section class="auth-visual"><img src="/img/background_login.webp" alt="자연과 향기를 담은 카리나벨" /><div class="auth-visual-shade"></div><div class="auth-visual-copy"><p>KARINABEL</p><h1>향기로 시작하는<br />나만의 특별한 순간</h1><span>자연의 생명력을 담은 순수한 향기를 만나보세요.</span></div></section>
        <section class="auth-panel"><button class="auth-home" type="button" aria-label="홈으로 이동" @click="goHome"><i class="fa-solid fa-arrow-left"></i> HOME</button><div class="auth-form-wrap"><img src="/img/logo2.png" alt="카리나벨" class="auth-logo" @click="goHome" /><p class="auth-eyebrow">WELCOME BACK</p><h2>로그인</h2><p class="auth-intro">회원번호와 비밀번호를 입력해 주세요.</p>
            <form novalidate @submit.prevent="handleLogin">
                <label class="auth-field"><span>회원번호 또는 아이디</span><div :class="['auth-input',{invalid:fieldError==='id'}]"><i class="fa-regular fa-user"></i><input v-model="memberIdOrId" type="text" autocomplete="username" placeholder="회원번호 또는 아이디" @input="clearError" /></div></label>
                <label class="auth-field"><span>비밀번호</span><div :class="['auth-input',{invalid:fieldError==='password'}]"><i class="fa-solid fa-lock"></i><input v-model="password" :type="showPassword?'text':'password'" autocomplete="current-password" placeholder="비밀번호" @input="clearError" /><button type="button" :aria-label="showPassword?'비밀번호 숨기기':'비밀번호 보기'" @click="showPassword=!showPassword"><i :class="showPassword?'fa-regular fa-eye-slash':'fa-regular fa-eye'"></i></button></div></label>
                <p v-if="errorMessage" class="auth-error" role="alert"><i class="fa-solid fa-circle-exclamation"></i>{{ errorMessage }}</p>
                <div class="auth-options"><label><input v-model="rememberMe" type="checkbox" /><span><i class="fa-solid fa-check"></i></span>아이디 저장</label><button type="button" @click="showModal=true">회원번호·비밀번호 찾기</button></div>
                <button class="auth-submit" type="submit" :disabled="isSubmitting"><span v-if="isSubmitting" class="auth-spinner"></span>{{ isSubmitting?'로그인 중...':'로그인' }}</button>
            </form>
            <div class="auth-divider"><span>OR</span></div><p class="auth-switch">아직 카리나벨 회원이 아니신가요?<RouterLink to="/signup">회원가입</RouterLink></p><p class="auth-help">로그인에 문제가 있다면 <a href="tel:042-822-2581">고객센터 042-822-2581</a>로 문의해 주세요.</p>
        </div></section><FindUserModal :visible="showModal" @close="showModal=false" />
    </main>
</template>
<script setup>
import { onMounted,ref } from "vue";import { useRoute,useRouter } from "vue-router";import { useStore } from "vuex";import AuthService from "@/api/AuthService";import FindUserModal from "@/components/FindUserModal.vue";
const router=useRouter(),route=useRoute(),store=useStore();const memberIdOrId=ref(""),password=ref(""),rememberMe=ref(false),showPassword=ref(false),showModal=ref(false),isSubmitting=ref(false),errorMessage=ref(""),fieldError=ref("");
const goHome=()=>router.push("/");const clearError=()=>{errorMessage.value="";fieldError.value=""};
const handleLogin=async()=>{clearError();if(!memberIdOrId.value.trim()){errorMessage.value="회원번호 또는 아이디를 입력해 주세요.";fieldError.value="id";return}if(!password.value){errorMessage.value="비밀번호를 입력해 주세요.";fieldError.value="password";return}isSubmitting.value=true;try{const response=await AuthService.login({memberIdOrId:memberIdOrId.value.trim(),password:password.value});await store.dispatch("login",response.data);rememberMe.value?localStorage.setItem("savedMemberId",memberIdOrId.value.trim()):localStorage.removeItem("savedMemberId");const redirect=typeof route.query.redirect==="string"&&route.query.redirect.startsWith("/")&&!route.query.redirect.startsWith("//")?route.query.redirect:"/products/onlymember";await router.replace(redirect)}catch(error){console.error(error);errorMessage.value=error.response?.data?.message||"회원번호 또는 비밀번호를 확인해 주세요."}finally{isSubmitting.value=false}};
onMounted(()=>{const saved=localStorage.getItem("savedMemberId");if(saved){memberIdOrId.value=saved;rememberMe.value=true}});
</script>
<style>
.auth-login-page{min-height:100vh;display:grid;grid-template-columns:1.05fr .95fr;background:#fff}.auth-visual{position:relative;min-height:100vh;overflow:hidden}.auth-visual>img{width:100%;height:100%;object-fit:cover}.auth-visual-shade{position:absolute;inset:0;background:linear-gradient(20deg,rgba(33,23,28,.75),rgba(40,25,31,.05))}.auth-visual-copy{position:absolute;left:clamp(35px,7vw,110px);bottom:10%;color:#fff}.auth-visual-copy>p{font-size:.67rem;font-weight:700;letter-spacing:.24em}.auth-visual-copy h1{margin:17px 0;font-family:Georgia,"Noto Serif KR",serif;font-size:clamp(2.6rem,4.2vw,4.7rem);font-weight:400;line-height:1.22}.auth-visual-copy span{color:#ddd5d8;font-size:.83rem}.auth-panel{position:relative;display:grid;place-items:center;padding:80px 40px}.auth-home{position:absolute;top:30px;right:38px;border:0;background:transparent;color:#8d8388;font-size:.67rem;letter-spacing:.1em}.auth-home i{margin-right:8px}.auth-form-wrap{width:min(100%,410px)}.auth-logo{width:150px;height:60px;margin:0 auto 30px;object-fit:contain;cursor:pointer}.auth-eyebrow{text-align:center;color:var(--color-accent);font-size:.64rem;font-weight:800;letter-spacing:.2em}.auth-form-wrap>h2{text-align:center;margin:8px 0 6px;font-family:Georgia,"Noto Serif KR",serif;font-size:2.5rem;font-weight:400}.auth-intro{text-align:center;margin-bottom:38px;color:#93898e;font-size:.78rem}.auth-field{display:block;margin-bottom:19px}.auth-field>span{display:block;margin-bottom:7px;color:#5e5559;font-size:.72rem;font-weight:700}.auth-input{height:52px;display:flex;align-items:center;border:1px solid #ddd5d8;transition:.2s}.auth-input:focus-within{border-color:var(--color-brand);box-shadow:0 0 0 3px rgba(134,101,119,.08)}.auth-input.invalid{border-color:#b8646e}.auth-input>i{width:45px;text-align:center;color:#aa9fa4;font-size:.8rem}.auth-input input{flex:1;height:100%;border:0;outline:0;background:transparent;font-size:.82rem}.auth-input button{width:45px;height:100%;border:0;background:transparent;color:#968b90}.auth-options{display:flex;justify-content:space-between;align-items:center;margin:6px 0 26px;color:#7d7378;font-size:.7rem}.auth-options label{display:flex;align-items:center;gap:7px;cursor:pointer}.auth-options input{position:absolute;opacity:0}.auth-options label>span{width:17px;height:17px;display:grid;place-items:center;border:1px solid #cfc6ca}.auth-options label>span i{opacity:0;color:#fff;font-size:.55rem}.auth-options input:checked+span{border-color:var(--color-brand);background:var(--color-brand)}.auth-options input:checked+span i{opacity:1}.auth-options button{border:0;background:transparent;color:#7d7378}.auth-error{margin:-4px 0 14px;color:#ad5964;font-size:.7rem}.auth-error i{margin-right:6px}.auth-submit{width:100%;height:54px;display:flex;align-items:center;justify-content:center;gap:9px;border:0;color:#fff;background:var(--color-brand-dark);font-size:.84rem;font-weight:700;letter-spacing:.04em}.auth-submit:disabled{opacity:.65}.auth-spinner{width:15px;height:15px;border:2px solid #ffffff55;border-top-color:#fff;border-radius:50%;animation:auth-spin .7s linear infinite}.auth-divider{display:flex;align-items:center;gap:12px;margin:27px 0;color:#b2a9ad;font-size:.6rem}.auth-divider:before,.auth-divider:after{content:"";height:1px;flex:1;background:#eee8ea}.auth-switch{text-align:center;color:#766c71;font-size:.74rem}.auth-switch a{margin-left:8px;color:var(--color-brand);font-weight:800;border-bottom:1px solid}.auth-help{margin-top:38px;text-align:center;color:#a69da1;font-size:.62rem}.auth-help a{color:#766b70}@keyframes auth-spin{to{transform:rotate(360deg)}}@media(max-width:850px){.auth-login-page{grid-template-columns:1fr}.auth-visual{display:none}.auth-panel{min-height:100vh;padding:75px 24px 50px}.auth-home{top:24px;right:24px}}@media(max-width:440px){.auth-panel{padding-inline:18px}.auth-form-wrap>h2{font-size:2.2rem}}
</style>
